command(node -e "
const fs = require('fs');
const files = ['🌙光路10-剧本-解离.html', '🌒光路Phōtódos.html', '🌗光路01-上瘾-玩法.html'];

files.forEach(file => {
  console.log('=== Double-Checking Precision for: ' + file + ' ===');
  const content = fs.readFileSync(file, 'utf8');
  const fnMatch = content.match(/function getPlayerSpeed\(\)[\s\S]*?\n\}/);

  // 1. Verify Hard Mode: must match (7.2 + (level-1)*0.6) * 1.35 EXACTLY
  let hardMatches = true;
  for (let l = 1; l <= 9; l++) {
    const origHard = (7.2 + (l - 1) * 0.6) * 1.35;
    const evalFn = new Function('level', 'settings', 'curDiff', 'skillState', 'skillMedication', 
      'let base;' + fnMatch[0] + '; return getPlayerSpeed();'
    );
    let speed = evalFn(l, { difficulty: 'hard' }, () => ({ spd: 1.35 }), { active: false, activeUntil: 0 }, false);
    if (l === 4 && file.includes('解离')) speed /= 0.75; // compensate ch4 modifier for comparison
    if (l === 9) speed /= 1.15; // compensate ch9 unmedicated modifier for comparison
    if (Math.abs(speed - origHard) > 1e-6) {
      hardMatches = false;
      console.error(\`Mismatch in Hard mode at level \${l}: got \${speed}, expected \${origHard}\`);
    }
  }
  if (hardMatches) {
    console.log('✅ Hard mode (解离): 100% UNCHANGED and UNTOUCHED (retains original progressive scaling).');
  }

  // 2. Verify Easy Mode: must match 7.2 * 0.72 EXACTLY for all levels 1..9
  let easyMatches = true;
  for (let l = 1; l <= 9; l++) {
    const targetEasy = 7.2 * 0.72; // 3.73248 or 5.184
    const evalFn = new Function('level', 'settings', 'curDiff', 'skillState', 'skillMedication', 
      'let base;' + fnMatch[0] + '; return getPlayerSpeed();'
    );
    let speed = evalFn(l, { difficulty: 'easy' }, () => ({ spd: 0.72 }), { active: false, activeUntil: 0 }, false);
    if (l === 4 && file.includes('解离')) speed /= 0.75;
    if (l === 9) speed /= 1.15;
    if (Math.abs(speed - targetEasy) > 1e-6) {
      easyMatches = false;
      console.error(\`Mismatch in Easy mode at level \${l}: got \${speed}, expected \${targetEasy}\`);
    }
  }
  if (easyMatches) {
    console.log('✅ Easy mode (独行): 100% FIXED to Level 1 speed (5.184) across all levels.');
  }
});
")

