  finale: document.getElementById("img_finale")
};

const CHAPTER_COLORS = {
  1: { bg1:"#0c0f17", bg2:"#07080d", bg3:"#040406" },
  2: { bg1:"#0f0d1a", bg2:"#090712", bg3:"#040308" },
  3: { bg1:"#170b16", bg2:"#0d050c", bg3:"#050205" },
  4: { bg1:"#1a100a", bg2:"#0f0905", bg3:"#060302" },
  5: { bg1:"#0b141a", bg2:"#050b0f", bg3:"#020406" },
  6: { bg1:"#1c1609", bg2:"#100c04", bg3:"#050301" },
  7: { bg1:"#1e0a0a", bg2:"#120404", bg3:"#060101" },
  8: { bg1:"#0a0c10", bg2:"#050608", bg3:"#020203" },
  9: { bg1:"#12101c", bg2:"#090812", bg3:"#030206" }
};

const CHAPTER_TITLES = {
  1: "第 1 章 · 童年",
  2: "第 2 章 · 小学",
  3: "第 3 章 · 初中",
  4: "第 4 章 · 高中",
  5: "第 5 章 · 大学",
  6: "第 6 章 · 电影",
  7: "第 7 章 · 坠落",
  8: "第 8 章 · 窗",
  9: "第 9 章 · 病院"
};

function renderLevel(lvl) {
  const c = CHAPTER_COLORS[lvl] || CHAPTER_COLORS[1];

  // 1. Base Radial Gradient
  const grd = ctx.createRadialGradient(W/2, H*0.42, 60, W/2, H/2, Math.max(W,H)*0.75);
  grd.addColorStop(0, c.bg1);
  grd.addColorStop(0.6, c.bg2);
  grd.addColorStop(1, c.bg3);
  ctx.fillStyle = grd;
  ctx.fillRect(0, 0, W, H);

  // 2. Draw In-Game Blended Background Image (screen composite at 0.05 globalAlpha)
  const img = imgs[lvl];
  if (img && img.complete && img.naturalWidth !== 0) {
    ctx.save();
    ctx.globalAlpha = 0.22; // Boost alpha slightly for high visibility preview
    ctx.globalCompositeOperation = "screen";
    ctx.drawImage(img, 0, 0, W, H);
    ctx.restore();
  }

  // 3. Draw Ambient Light Particles & Player Light Ball
  const now = Date.now();
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  for(let i = 0; i < 40; i++) {
    const px = (Math.sin(i * 17 + now * 0.0005) * 0.5 + 0.5) * W;
    const py = (Math.cos(i * 29 + now * 0.0005) * 0.5 + 0.5) * H;
    const r = 2 + Math.sin(now * 0.002 + i) * 1.5;
    ctx.fillStyle = "rgba(255, 230, 180, 0.15)";
    ctx.beginPath(); ctx.arc(px, py, r, 0, Math.PI * 2); ctx.fill();
  }

  // Draw Player Light Ball
  const px = 400, py = 320;
  const pGrd = ctx.createRadialGradient(px, py, 0, px, py, 45);
  pGrd.addColorStop(0, "rgba(255, 255, 240, 1)");
  pGrd.addColorStop(0.3, "rgba(255, 220, 150, 0.8)");
  pGrd.addColorStop(1, "rgba(255, 180, 80, 0)");
  ctx.fillStyle = pGrd;
  ctx.beginPath(); ctx.arc(px, py, 45, 0, Math.PI * 2); ctx.fill();
  ctx.restore();

  // Draw Level Title Overlay
  ctx.save();
  ctx.fillStyle = "rgba(240, 235, 220, 0.85)";
  ctx.font = "bold 20px sans-serif";
  ctx.fillText(CHAPTER_TITLES[lvl], 30, 45);
  ctx.restore();
}

function renderFinale() {
  ctx.fillStyle = "rgb(8,8,10)";
  ctx.fillRect(0, 0, W, H);

  const img = imgs.finale;
  if (img && img.complete && img.naturalWidth !== 0) {
    ctx.save();
    ctx.globalAlpha = 0.35;
    ctx.globalCompositeOperation = "screen";
    ctx.drawImage(img, 0, 0, W, H);
    ctx.restore();
  }

  // Dark overlay
  ctx.fillStyle = "rgba(8,8,10,0.65)";
  ctx.fillRect(0, 0, W, H);

  // Minimal text
  ctx.save();
  ctx.fillStyle = "#e4e1d6";
  ctx.font = "italic 42px serif";
  ctx.textAlign = "center";
  ctx.fillText("喵。", W/2, H/2);
  ctx.restore();
}

window.addEventListener("load", async () => {
  // Wait for all image decoding
  const allImgs = Object.values(imgs);
  await Promise.all(allImgs.map(img => img.decode().catch(() => {})));
  console.log("All background images successfully preloaded and decoded!");
  window.__readyToRender = true;
});
</script>
</body>
</html>
`;

