command(python3 -c "
import json, subprocess

locales = {}
for lang in ['zh', 'en', 'de', 'pt', 'ru']:
    with open(f'locales/locales-{lang}.json', encoding='utf-8') as f:
        locales[lang] = json.load(f)

json_str = json.dumps(locales, ensure_ascii=False)

script = f'''
const INLINE_LOCALES = {json_str};
(function(){{
  const LOCALES = window.PHOTODOS_LOCALES || INLINE_LOCALES;
  const LANGS = ['zh', 'en', 'de', 'pt', 'ru'];
  const NAMES = {{zh:'中文', en:'EN', de:'DE', pt:'PT', ru:'RU'}};
  const FULL_NAMES = {{zh:'简体中文', en:'English', de:'Deutsch', pt:'Português', ru:'Русский'}};
  let currentLang = 'zh';

  try {{
    const saved = localStorage.getItem('photodos-lang');
    if (saved && LANGS.indexOf(saved) !== -1) {{
      currentLang = saved;
    }} else {{
      const navLang = (navigator.language || navigator.userLanguage || '').toLowerCase();
      if (navLang.startsWith('en')) currentLang = 'en';
      else if (navLang.startsWith('de')) currentLang = 'de';
      else if (navLang.startsWith('pt')) currentLang = 'pt';
      else if (navLang.startsWith('ru')) currentLang = 'ru';
    }}
  }} catch(e){{}}

  window.t = function(key){{
    if (!key) return '';
    const parts = String(key).split('.');
    let val = LOCALES[currentLang];
    for (let i = 0; i < parts.length; i++) {{
      if (val == null) break;
      val = /^\\d+$/.test(parts[i]) ? val[parseInt(parts[i],10)] : val[parts[i]];
    }}
    if (val == null) {{
      val = LOCALES.zh || LOCALES.en;
      for (let j = 0; j < parts.length; j++) {{
        if (val == null) break;
        val = /^\\d+$/.test(parts[j]) ? val[parseInt(parts[j],10)] : val[parts[j]];
      }}
    }}
    return val == null ? key : val;
  }};

  window.formatChapterTitle = function(levelNum){{
    const idx = Math.min(Math.max(1, levelNum) - 1, 8);
    const prefixTpl = (typeof t === 'function' && (t('intro_card.chapter_prefix') || t('menu.chapter_prefix'))) || '第{{n}}章 · ';
    const chName = (typeof CHAPTER_NAMES !== 'undefined' && CHAPTER_NAMES[idx]) ? CHAPTER_NAMES[idx] : '';
    return prefixTpl.replace('{{n}}', idx + 1) + chName;
  }};

  window.applyI18n = function(lang){{
    if (LANGS.indexOf(lang) === -1) return;
    currentLang = lang;
    try {{ localStorage.setItem('photodos-lang', lang); }} catch(e){{}}
    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : lang;
    document.documentElement.className = 'lang-' + lang;

    // 1) Re-render data-i18n elements
    document.querySelectorAll('[data-i18n]').forEach(function(el){{
      const k = el.getAttribute('data-i18n');
      const v = t(k);
      if (v != null && v !== k) {{
        if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') el.placeholder = v;
        else el.textContent = v;
      }}
    }});
    document.querySelectorAll('[data-i18n-html]').forEach(function(el){{
      const k = el.getAttribute('data-i18n-html');
      const v = t(k);
      if (v != null && v !== k) el.innerHTML = v;
    }});

    // 2) Update dynamic difficulty labels
    if (typeof DIFFS !== 'undefined') {{
      const easyLabel = t('menu.difficulty_easy');
      const hardLabel = t('menu.difficulty_hard');
      if (easyLabel && easyLabel !== 'menu.difficulty_easy') DIFFS.easy.label = easyLabel;
      if (hardLabel && hardLabel !== 'menu.difficulty_hard') DIFFS.hard.label = hardLabel;

      document.querySelectorAll('.diff-dot').forEach(function(dot){{
        const k = dot.dataset.k;
        if (DIFFS[k]) {{
          dot.dataset.label = DIFFS[k].label;
          dot.setAttribute('aria-label', DIFFS[k].label);
        }}
      }});
      const dRowEasy = document.querySelector('#diff-row [data-k=\"easy\"]');
      const dRowHard = document.querySelector('#diff-row [data-k=\"hard\"]');
      if (dRowEasy && DIFFS.easy) dRowEasy.textContent = DIFFS.easy.label;
      if (dRowHard && DIFFS.hard) dRowHard.textContent = DIFFS.hard.label;
    }}

    // 3) Update in-game HUD
    const scoreLbl = document.getElementById('score-label');
    if (scoreLbl) scoreLbl.textContent = t('menu.light_label') || 'LIGHT';
    const meterLbl = document.getElementById('meter-label');
    if (meterLbl) meterLbl.textContent = t('menu.anchor_label') || 'ANCHOR';
    const meterFull = document.getElementById('meter-full');
    if (meterFull) meterFull.textContent = t('menu.anchor_ready') || 'ANCHOR READY';

    // 4) Update overlays instructions
    const instDiff = document.getElementById('instruct-diff');
    if (instDiff) instDiff.innerHTML = t('intro_card.hint_difficulty') || t('menu.instruct_difficulty') || '- 【独行】 / + 【解离】';
    const instBegin = document.getElementById('instruct-begin');
    if (instBegin) instBegin.innerHTML = '<span class=\"highlight\">Space</span> - ' + (t('intro_card.hint_begin') || 'begin');
    const introHintDiff = document.getElementById('intro-hint-diff');
    if (introHintDiff) introHintDiff.innerHTML = t('intro_card.hint_difficulty') || t('menu.intro_hint_difficulty') || '- 【独行】 / + 【解离】';
    const introHintBegin = document.getElementById('intro-hint-begin');
    if (introHintBegin) introHintBegin.innerHTML = '<span class=\"highlight\">Space</span> - ' + (t('intro_card.hint_begin') || 'begin');
    const clearHint = document.getElementById('clear-hint');
    if (clearHint) clearHint.innerHTML = t('clear_card.hint_continue') || t('menu.clear_hint') || '按 <span class=\"highlight\">空格</span> 继续';

    // 5) Rebuild chapter and skill objects
    if (typeof CHAPTER_NAMES !== 'undefined') {{
      for (let i = 1; i <= 9; i++) CHAPTER_NAMES[i-1] = t('chapters.' + i + '.name');
    }}
    if (typeof CHAPTER_SUBS !== 'undefined') {{
      for (let i = 1; i <= 9; i++) CHAPTER_SUBS[i-1] = t('chapters.' + i + '.sub');
    }}
    if (typeof CHAPTER_LINES !== 'undefined') {{
      for (let i = 1; i <= 9; i++) {{
        const c = CHAPTER_LINES[i];
        if (c) {{
          c.blackShadow = t('chapters.' + i + '.blackShadow');
          c.purpleShadow = t('chapters.' + i + '.purpleShadow');
          c.badEnd = t('chapters.' + i + '.badEnd');
          c.clear = t('chapters.' + i + '.clear');
          c.anchor = t('chapters.' + i + '.anchor');
        }}
      }}
    }}
